using System;
using System.Linq;
using System.Collections.Generic;
namespace KingswayWorkshop;
public static class Adapters {
 // Every boss and quest slot with a single enemy object. They all share the same adapter:
 // original Create (drops, quest flags, alarms) runs first, the authored attack replaces
 // User 0 (which also turns off native alt attacks), and any death tail is deferred.
 public static readonly string[] Spirits={"obj_Brogt","obj_DarkBrogt","obj_Corym","obj_DarkCorym","obj_Kytgol","obj_DarkKytgol","obj_Falront","obj_DarkFalront","obj_Moorv","obj_DarkMoorv","obj_Myrgel","obj_DarkMyrgel"};
 public static readonly string[] Endgame={"obj_Princess","obj_DemonLord","obj_CosmosKing","obj_CosmosWorm","obj_Skyeater"};
 public static readonly string[] Single=Spirits.Concat(new[]{"obj_TombBoss","obj_HauntedHouseBoss","obj_ThiefBoss"}).Concat(Endgame).ToArray();
 public static readonly Dictionary<string,string> DemonParts=new(){["Head"]="obj_DemonBossHead",["Body"]="obj_DemonBossButt",["Arms"]="obj_DemonBossArms",["Legs"]="obj_DemonBossLegs"};
 public static void Configure(Catalog cat){foreach(var slot in Single){var a=cat.Adapters.FirstOrDefault(x=>x.Slot==slot);if(a==null){a=new(){Slot=slot};cat.Adapters.Add(a);}a.Classification="supported";a.Reason=Spirits.Contains(slot)?"Spirit boss (Guardian Fire): preserve original identity, guaranteed relic/quest drops, cannot-escape rule, native timers and reward events.":Endgame.Contains(slot)?(slot=="obj_Skyeater"?"Shadow ending: preserve original identity, summons timer and the ending started when it is killed. Authored health and movement replace the forced 9999 health and centred window.":"Endgame encounter: preserve original identity, drop slots, cannot-escape rule and native timers/summons; the throne or ending event continues natively."):"Quest encounter: preserve original identity, kill credit, reward slots and completion callback; defer callback while group hostiles remain.";a.ReplaceableEvents=new(){"Create: append combat/presentation fields after original initializer","User 0: generated attack"};a.ProtectedEvents=new(){"Original Create initializer and drop slots","Native Begin Step level scaling","User 10: native rewards, original completion tail deferred","User 11: original loot presentation and drop generation","All unlisted events remain original"};a.MandatoryEvidence=new(){"gml_Object_"+slot+"_Create_0","gml_Object_"+slot+"_Other_20","gml_Object_"+slot+"_Step_1"};}
  var d=cat.Adapters.FirstOrDefault(x=>x.Slot=="obj_DemonBossSpawner");if(d==null){d=new(){Slot="obj_DemonBossSpawner"};cat.Adapters.Add(d);}d.Classification="conditionally supported";d.Reason="Four-part Demon King: retain spawner and original Head, Body, Arms, Legs object IDs. Head owns all limbs; original cross-object damage is replaced by explicit structural death actions. Spawner layout is preserved; combat completes after surviving separate actors/summons.";d.RequiredComponents=DemonParts.Keys.ToList();d.ReplaceableEvents=new(){"Part Create: append configuration","Part User 0: generated attack","Part User 10: explicit structural ownership replaces global with-object damage"};d.ProtectedEvents=new(){"Spawner Create, Step and Alarm layout/controller behavior","Spawner End Step original four object creations; append explicit group attachment","Part native initialization, window lifecycle and rewards"};d.Dependencies=DemonParts.Values.ToList();d.MandatoryEvidence=new(){"No native item drop slots on these four parts; all are -4","Original part death events contain only inherited rewards, destroy and global structural damage; those relationships are explicitly replaceable"};
 }
}
